steps.script:
$ErrorActionPreference='Stop'
$a='TT Actualidad - Imagenes pendientes APP';$b='TT Actualidad - Entrega IA gradual'
$x=Get-ScheduledTask $a -ErrorAction SilentlyContinue
$y=Get-ScheduledTask $b -ErrorAction SilentlyContinue
$o=@{old=$(if($x){$x.State}else{'absent'});new=$(if($y){$y.State}else{'absent'});operation='none'}
$t=Join-Path $env:TEMP ('TTInbox-'+[guid]::NewGuid().ToString('N')+'.ps1')
$changed=$false;$phase='preflight'
try{
 if($y -and $y.State -eq 'Running'){$o.operation='already_running'}
 elseif($x -and $x.State -eq 'Running'){$o.operation='legacy_running_no_overlap'}
 else{
 $phase='download'
 $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/7c13f234640d5d75df1dee0dc0173544479ae969/windows/Instalar-Entrega-IA-Gradual-TT.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $t -TimeoutSec 30
 $src=[IO.File]::ReadAllText($t,[Text.Encoding]::UTF8)
 if(-not $src.Contains('function provesExactNewImageJob(task,job)') -or -not $src.Contains('NO_APPROVAL_NO_PUBLICATION')){throw 'MARKER_MISMATCH'}
 $tokens=$null;$errors=$null
 [Management.Automation.Language.Parser]::ParseFile($t,[ref]$tokens,[ref]$errors)|Out-Null
 if($errors.Count){throw 'SYNTAX_INVALID'}
 $phase='switch'
 if($x -and $x.State -ne 'Disabled'){Disable-ScheduledTask $a|Out-Null;$changed=$true}
 $phase='install'
 & $t -Apply *> $null
 if(-not $?){throw 'INSTALLER_FAILED'}
 $y=Get-ScheduledTask $b -ErrorAction Stop
 if($y.State -eq 'Disabled'){throw 'NEW_TASK_DISABLED'}
 $o.operation='installed_and_started'
 }
 $y=Get-ScheduledTask $b -ErrorAction SilentlyContinue
 $o.newAfter=$(if($y){$y.State}else{'absent'})
 $info=Get-ScheduledTaskInfo $b -ErrorAction SilentlyContinue
 if($info){$o.lastResult=$info.LastTaskResult}
}catch{
 $o.operation='error';$o.phase=$phase
 $o.error=([string]$_.Exception.Message -replace 'https?://\S+','[URL]')
 $y=Get-ScheduledTask $b -ErrorAction SilentlyContinue
 if($changed -and (-not $y -or $y.State -eq 'Disabled')){Enable-ScheduledTask $a -ErrorAction SilentlyContinue|Out-Null;$o.legacyRestored=$true}
}finally{Remove-Item $t -Force -ErrorAction SilentlyContinue}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 4))
